insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('engine-air-filter-replacement','engine','Replace the engine air filter','bentley-e34-upload','020-10, Figs. 5–6; PDF 32',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"engine-air-filter-replacement","title":"Replace the engine air filter","system":"engine","kind":"replacement","duration":"15–25 min","summary":"Open the factory clip-fastened airbox, replace the element and check the perimeter seal before starting the engine.","applicability":"Bentley-covered U.S. 525i, 535i, 530i and 540i with the original two-piece, spring-clipped intake housing. Confirm the installed housing and element on cars with intake changes.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-10, Figs. 5–6","pdfPages":[32]},"tools":["Correct engine air filter element","Clean lint-free cloth","Light"],"cautions":["Switch the ignition off and let the engine cool. Keep grit and tools clear of the clean-side intake opening.","Support the airbox lid and attached intake duct. Stop if age-hardened plastic or wiring prevents access without force."],"steps":[{"title":"Locate the airbox and check the replacement","body":"Follow the intake duct to its rectangular filter housing. Bentley locates the M20/M50 housing at the left front and the M30/M60 housing at the right front, using vehicle left and right. Confirm the element against the installed housing.","check":"The replacement matches the filter outline, depth and sealing lip."},{"title":"Release the perimeter clips","body":"Note how the upper lid locates in the lower housing. Release the spring clips around the joint and lift the lid only far enough to withdraw the filter. Keep the lid supported so it does not pull on the duct or airflow-meter wiring.","check":"The filter lifts out without straining a hose, wire or clip."},{"title":"Clean the housing and seat the element","body":"Note which side of the old filter faced incoming air. Wipe dirt from the housing with a lint-free cloth, keeping debris out of the outlet to the engine. Seat the replacement in the same orientation and follow any locating features on its frame.","check":"The filter lies flat and the seal follows the housing edge with no fold or gap."},{"title":"Close and inspect the intake","body":"Engage the lid locators, lower the lid evenly and refasten each clip. Check the attached intake duct and connector for anything disturbed during access. Remove the cloth and tools before starting.","check":"The airbox joint is closed all around and every fastener and disturbed connection is secure."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('windshield-wiper-blade-replacement','electrical','Replace the front windshield wiper blades','bentley-e34-upload','020-18 and 611-1 to 611-2, Fig. 1; PDF 40,387,388',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"windshield-wiper-blade-replacement","title":"Replace the front windshield wiper blades","system":"electrical","kind":"replacement","duration":"15–20 min","summary":"Release the original front blade retainers, seat each replacement and check sweep and park on wet glass.","applicability":"Front windshield blade assemblies on Bentley-covered U.S. E34s with the retainer shown in group 611. Check both blade lengths and adapters. Touring rear blades, rubber inserts and wiper-arm adjustment are separate jobs.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-18 and 611-1 to 611-2, Fig. 1","pdfPages":[40,387,388]},"tools":["Correct left and right blade assemblies","Folded towel","Water or washer fluid"],"cautions":["Park the wipers and turn the ignition off before lifting an arm. Hold the spring-loaded arm whenever the blade is off.","Lay a folded towel on the glass under the arm. Stop if the arm will not lift freely or the new adapter does not latch."],"steps":[{"title":"Match the attachment on each arm","body":"Compare blade lengths and the attachment to the installed hardware. Work on one side at a time and identify the spring tab or pair of tabs before releasing the blade.","check":"The correct replacement is ready for this arm and its latch matches."},{"title":"Release the blade without dropping the arm","body":"Lift the arm off the protected windshield. Turn the blade roughly across the arm to reach the latch. Hold the arm steady, press the retaining tab or tabs and slide the blade out of the attachment.","check":"The old blade is free and the bare arm is still supported above the glass."},{"title":"Fit and test the new blade lock","body":"Slide the new assembly into the mount until its retainer engages. Gently pull against the latch by hand before lowering the arm onto the glass. Repeat for the other side.","check":"Neither blade slides out, and both sit normally against the windshield."},{"title":"Verify sweep and park","body":"Remove the towel, wet the glass and test the wipers from the driver’s seat with hands clear. Check both blades for clearance through the sweep and see whether they return to their parked position. Stop if a blade moves on the arm, strikes trim or leaves visibility impaired.","check":"Both blades stay attached, wipe cleanly and return to park without interference."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('accessory-drive-belt-inspection','engine','Inspect accessory drive belts for wear','bentley-e34-upload','020-12 to 020-13, Figs. 9–11; PDF 34,35',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"accessory-drive-belt-inspection","title":"Inspect accessory drive belts for wear","system":"engine","kind":"inspection","duration":"10–20 min","summary":"Identify the visible belt arrangement and check for glazing, cracking, separation, contamination or poor tracking with the engine off.","applicability":"Factory accessory drives on the covered U.S. E34 engines. Bentley groups M20/M30 V-belts separately from M50/M60 poly-ribbed belts. Verify the actual tensioner and routing before any replacement.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-12 to 020-13, Figs. 9–11","pdfPages":[34,35]},"tools":["Flashlight","Inspection mirror","Camera"],"cautions":["Engine off, key out and engine cool. Keep hands and tools clear of fans, belts and pinch points.","This check is visual. Releasing a tensioner or turning the engine to expose the rest of a belt requires its own procedure."],"steps":[{"title":"Separate the accessory belts from the timing drive","body":"Identify the visible belts driving accessories at the front of the engine. Note the narrow V-profile or multiple small ribs, and count the visible belts. The M20 camshaft belt under its cover is outside this inspection.","check":"You have recorded the belt type and the visible route for each accessory belt."},{"title":"Inspect each accessible span","body":"Use a light and mirror to inspect the visible faces and edges. Look for polished contact surfaces, cracks, loose strands, separated layers, missing ribs or wet oil. Record which surfaces you could see and which remained hidden.","check":"Photos identify the affected belt, location and type of damage."},{"title":"Check belt seating and nearby traces","body":"Look for a belt riding at an angle, on a pulley edge or outside its expected grooves. If there is fluid on the belt, look for traces above or beside it from a safe position. Note a reported squeal separately from the visible condition.","check":"The record separates belt condition, seating and any possible leak."},{"title":"Decide what needs further work","body":"A torn, displaced or contaminated belt needs assessment before the engine is run again. Establish the correct routing, belt and tensioning hardware before replacement, and address the source of contamination. Do not use belt dressing to mask a squeal.","check":"The next action accounts for the specific belt and observed fault."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('brake-fluid-level-inspection','brakes','Check the brake and clutch fluid reservoir','bentley-e34-upload','020-15, Fig. 16; 020-16; PDF 37,38',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"brake-fluid-level-inspection","title":"Check the brake and clutch fluid reservoir","system":"brakes","kind":"inspection","duration":"5–10 min","summary":"Read the brake reservoir level through the wall and document a low or falling level for hydraulic diagnosis.","applicability":"Bentley-covered U.S. E34s with the original marked brake-fluid reservoir. On manual-transmission cars the brake reservoir also feeds the hydraulic clutch. This is an external level check.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-15, Fig. 16; 020-16","pdfPages":[37,38]},"tools":["Flashlight","Camera or service log"],"cautions":["Keep the reservoir closed. Fluid is poisonous and can damage painted surfaces.","If the level is below MIN, there is an active leak, or the pedal is soft or sinking, do not drive. Arrange inspection and recovery."],"steps":[{"title":"Identify the correct reservoir","body":"Park on level ground with the engine off. Find the reservoir at the brake master cylinder. Verify its markings and distinguish it from the coolant and steering reservoirs.","check":"The MIN and MAX marks you are reading are on the brake-fluid reservoir."},{"title":"Read the level against both marks","body":"Look squarely at the marked wall using a light. Record the level in relation to MIN and MAX and whether the marks and fluid line were visible. If you cannot read it reliably, leave the observation unresolved.","check":"The record includes a visible level and date, or states that the reading was inconclusive."},{"title":"Capture any symptoms and change over time","body":"Note any warning lamp, change in pedal behavior or visible wetness near the reservoir or hydraulic connections. A gradual change can accompany pad wear, while a low or falling level also warrants a leak check. On a manual car include any change in clutch behavior.","check":"The next inspection can distinguish brake wear, brake hydraulic leakage and possible clutch hydraulic leakage."},{"title":"Route a low reading to diagnosis","body":"Keep a dated photo and describe the level and symptoms together. Use the brake and clutch source sections as applicable to have the loss investigated before returning the car to service.","check":"A low reading remains open until its cause is resolved."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('power-steering-fluid-level-inspection','suspension','Identify and check the power-steering fluid','bentley-e34-upload','020-15, Fig. 15; PDF 37',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"power-steering-fluid-level-inspection","title":"Identify and check the power-steering fluid","system":"suspension","kind":"inspection","duration":"10–15 min","summary":"Read the reservoir marking and dipstick on the applicable steering system, then record the level and any evidence of leakage.","applicability":"Bentley-covered U.S. E34s with a labeled reservoir and MIN/MAX dipstick as shown in Fig. 15. Verify the installed hydraulic configuration and any shared systems before using a service procedure.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-15, Fig. 15","pdfPages":[37]},"tools":["Clean lint-free cloth","Flashlight","Camera"],"cautions":["Use level ground, engine off. Clean around the cap before opening and keep dirt out of the reservoir.","ATF and CHF systems require different fluids. Verify the installed system and applicable specification before adding anything."],"steps":[{"title":"Confirm the reservoir identity","body":"Find the steering-fluid reservoir and read its marking before opening it. Record the label exactly and note whether the car has shared hydraulic equipment or replacement parts. A faded or missing label leaves fluid identity unresolved.","check":"The reservoir is identified and its label or lack of one is documented."},{"title":"Read the dipstick marks","body":"On the source-shown unit, remove the cap and inspect the integral dipstick. Use the matching vehicle procedure for the dipstick seating and read the fluid line against the MIN and MAX marks. Refit the cap securely by hand.","check":"The reading is recorded with its conditions, and the cap is back in place."},{"title":"Look for a source of loss","body":"From above, inspect the reservoir and accessible hose connections for fresh wetness. Note any recent fluid additions, steering noise or change in assistance. A level check alone cannot identify a bad pump or steering box.","check":"Low or falling level, leaks or loss of assistance have a separate diagnosis before further use."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('cold-tire-pressure-check','suspension','Check and set cold tire pressures','bentley-e34-upload','020-16, tire inflation; PDF 38',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"cold-tire-pressure-check","title":"Check and set cold tire pressures","system":"suspension","kind":"inspection","duration":"10–15 min","summary":"Match the door-pillar placard to your tires and load, measure each wheel cold and track repeat losses.","applicability":"Factory tire sizes and load combinations listed for the actual vehicle. For a non-listed tire size, confirm the correct cold settings for the installed combination before adjusting.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-16, tire inflation","pdfPages":[38]},"tools":["Tire pressure gauge","Air supply","Driver-door pillar placard or matching owner’s manual"],"cautions":["Check when the tires are cold. Use the vehicle’s cold pressure for the applicable axle and load, within the tire’s limits.","Do not bleed a hot tire down to the cold target. A visibly damaged tire or one that will not hold pressure needs inspection before driving."],"steps":[{"title":"Read the correct placard row","body":"Compare the front and rear tire sizes with the driver-door pillar placard or matching owner’s manual. Choose the load condition that applies and record both axle targets in the units shown.","check":"You have a verified front and rear cold target for the actual tire sizes and load."},{"title":"Measure before adding air","body":"Wait at least three hours after driving for a cold reading. Remove each valve cap and seat the gauge squarely until the reading stabilizes. Record the four readings by wheel position and note any one tire substantially lower than the rest.","check":"All four readings and their units are recorded before adjustment."},{"title":"Set each tire and recheck it","body":"Adjust in short increments to the appropriate axle target, rechecking with the same gauge. Refit the valve caps. If the car has a serviceable spare, check it separately against its own specified pressure.","check":"Each wheel is at its verified target and each valve has its cap."},{"title":"Follow up on repeat loss","body":"Save the date, ambient conditions and readings. If one tire repeatedly loses more pressure than the others, have the tire, valve and wheel inspected for leakage. A pressure adjustment does not repair a puncture or damaged sidewall.","check":"The next cold measurement can be compared wheel by wheel."}]}'::jsonb) on conflict do nothing;
